// src/components/StudentManagement.js
import React, { useState, useEffect } from 'react';
import { Table, Modal, Form, Input, Select, message, Space, Popconfirm, Button, Alert, Row, Col, Typography, Card, Statistic, Spin } from 'antd';
import { PlusCircleOutlined, EditOutlined, DeleteOutlined, UserOutlined, MailOutlined, TeamOutlined, FilePdfOutlined, SearchOutlined } from '@ant-design/icons';
import { Pie } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { fetchEtudiants, createEtudiant, updateEtudiant, deleteEtudiant, fetchClasses } from '../services/apiService';

// Register Chart.js components
ChartJS.register(ArcElement, Tooltip, Legend);

const { Option } = Select;
const { Title } = Typography;

// Load jsPDF and jspdf-autotable via CDN
const loadPdfLibs = () => {
    return new Promise((resolve, reject) => {
        if (window.jspdf && window.jspdf.jsPDF && window.jspdf.jsPDF.autoTable) {
            resolve();
            return;
        }

        const scriptJsPDF = document.createElement('script');
        scriptJsPDF.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
        scriptJsPDF.onload = () => {
            const scriptAutoTable = document.createElement('script');
            scriptAutoTable.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.5.25/jspdf.plugin.autotable.min.js';
            scriptAutoTable.onload = resolve;
            scriptAutoTable.onerror = reject;
            document.head.appendChild(scriptAutoTable);
        };
        scriptJsPDF.onerror = reject;
        document.head.appendChild(scriptJsPDF);
    });
};
const espritLogoBase64 = 'data:image/png;base64,'; // Remplace ceci par ton vrai logo Esprit en base64

const StudentManagement = ({ currentUser }) => {
    const [etudiants, setEtudiants] = useState([]);
    const [classes, setClasses] = useState([]);
    const [loading, setLoading] = useState(false);
    const [modalVisible, setModalVisible] = useState(false);
    const [selectedStudent, setSelectedStudent] = useState(null);
    const [form] = Form.useForm();
    const [pdfLibsLoaded, setPdfLibsLoaded] = useState(false);
    const [pieData, setPieData] = useState({ labels: [], datasets: [] });
    const [searchText, setSearchText] = useState('');
    const [filteredEtudiants, setFilteredEtudiants] = useState([]);

    // Load PDF libraries
    useEffect(() => {
        loadPdfLibs()
            .then(() => setPdfLibsLoaded(true))
            .catch(error => {
                message.error("Échec du chargement des bibliothèques PDF: " + error.message);
                console.error("Failed to load PDF libraries:", error);
            });
    }, []);

    // Compute pie chart data when etudiants changes
    useEffect(() => {
        const classCounts = etudiants.reduce((acc, student) => {
            const className = student.classe ? student.classe.nom : 'Sans classe';
            acc[className] = (acc[className] || 0) + 1;
            return acc;
        }, {});

        const labels = Object.keys(classCounts);
        const values = Object.values(classCounts);

        const chartData = {
            labels: labels,
            datasets: [
                {
                    data: values,
                    backgroundColor: ['#FF4D4F', '#FF6B6B', '#FF8787', '#FFA3A3', '#FFBFBF'], // Red gradient
                    borderColor: ['#FFFFFF'],
                    borderWidth: 1,
                },
            ],
        };

        setPieData(chartData);
    }, [etudiants]);

    // Filter students based on search text
    useEffect(() => {
        const lowercasedSearchText = searchText.toLowerCase();
        const filtered = etudiants.filter(student =>
            (student.nom && student.nom.toLowerCase().includes(lowercasedSearchText)) ||
            (student.email && student.email.toLowerCase().includes(lowercasedSearchText))
        );
        setFilteredEtudiants(filtered);
    }, [searchText, etudiants]);

    // Chart.js pie chart options
    const pieOptions = {
        responsive: true,
        plugins: {
            legend: {
                position: 'bottom',
                labels: {
                    font: { size: 12 },
                    color: '#333',
                },
            },
            tooltip: {
                callbacks: {
                    label: function (context) {
                        const total = context.dataset.data.reduce((sum, val) => sum + val, 0);
                        const value = context.raw;
                        const percentage = ((value / total) * 100).toFixed(1);
                        return `${context.label}: ${value} (${percentage}%)`;
                    },
                },
            },
        },
    };

    // Load students
    useEffect(() => {
        if (!currentUser?.authToken || currentUser.role !== 'ADMIN') {
            setEtudiants([]);
            return;
        }
        setLoading(true);
        fetchEtudiants(currentUser.authToken)
            .then(data => {
                setEtudiants(data);
                setLoading(false);
            })
            .catch(error => {
                message.error('Échec du chargement des étudiants: ' + error.message);
                setEtudiants([]);
                setLoading(false);
            });
    }, [currentUser?.authToken, currentUser?.role]);

    // Load classes for dropdown
    useEffect(() => {
        if (!currentUser?.authToken) return;
        fetchClasses(currentUser.authToken)
            .then(data => setClasses(data))
            .catch(error => message.error('Échec du chargement des classes pour la sélection: ' + error.message));
    }, [currentUser?.authToken]);

    const handleDeleteEtudiant = async (id) => {
        try {
            await deleteEtudiant(id, currentUser.authToken);
            message.success('Étudiant supprimé avec succès');
            fetchEtudiants(currentUser.authToken)
                .then(data => setEtudiants(data))
                .catch(error => message.error('Échec du chargement des étudiants: ' + error.message));
        } catch (error) {
            message.error('Échec de la suppression de l\'étudiant: ' + error.message);
        }
    };

    const handleEtudiantSubmit = async () => {
        try {
            const values = await form.validateFields();
            const studentData = { ...values, classe: { id: parseInt(values.classeId) } };
            if (selectedStudent) {
                await updateEtudiant(selectedStudent.id, studentData, currentUser.authToken);
                message.success('Étudiant mis à jour avec succès');
            } else {
                await createEtudiant(studentData, currentUser.authToken);
                message.success('Étudiant créé avec succès');
            }
            setModalVisible(false);
            fetchEtudiants(currentUser.authToken)
                .then(data => setEtudiants(data))
                .catch(error => message.error('Échec du chargement des étudiants: ' + error.message));
        } catch (error) {
            message.error(error.message || 'Opération échouée');
        }
    };

    const handleExportStudentsPdf = async () => {
        if (!pdfLibsLoaded) {
            message.error("Les bibliothèques PDF ne sont pas encore chargées. Veuillez réessayer.");
            return;
        }

        if (!currentUser?.authToken || currentUser.role !== 'ADMIN') {
            message.error("Accès non autorisé pour exporter les étudiants.");
            return;
        }

        setLoading(true);
        try {
            const studentsToExport = await fetchEtudiants(currentUser.authToken);

            if (!studentsToExport || studentsToExport.length === 0) {
                message.info("Aucun étudiant à exporter.");
                setLoading(false);
                return;
            }

            const doc = new window.jspdf.jsPDF();

            doc.addImage(espritLogoBase64, 'PNG', 14, 10, 30, 15);
            doc.setFontSize(20);
            doc.setFont("helvetica", "bold");
            doc.setTextColor(220, 20, 60);
            doc.text("Liste des Étudiants", 105, 22, { align: 'center' });

            const tableColumn = ["ID", "Nom", "Email", "Classe"];
            const tableRows = studentsToExport.map(student => [
                student.id,
                student.nom,
                student.email,
                student.classe ? student.classe.nom : 'N/A'
            ]);

            doc.autoTable({
                head: [tableColumn],
                body: tableRows,
                startY: 35,
                theme: 'striped',
                headStyles: { fillColor: [255, 105, 180] },
                styles: { fontSize: 10, cellPadding: 3 },
                columnStyles: {
                    0: { cellWidth: 20 },
                    1: { cellWidth: 50 },
                    2: { cellWidth: 60 },
                    3: { cellWidth: 40 }
                }
            });

            doc.save(`liste_etudiants_${new Date().toISOString().slice(0, 10)}.pdf`);
            message.success('Liste des étudiants exportée avec succès au format PDF !');
        } catch (error) {
            message.error('Échec de l\'exportation des étudiants en PDF: ' + error.message);
            console.error("PDF Export Error:", error);
        } finally {
            setLoading(false);
        }
    };

    const columns = [
        {
            title: 'Nom',
            dataIndex: 'nom',
            key: 'nom',
            sorter: (a, b) => a.nom.localeCompare(b.nom),
            sortDirections: ['ascend', 'descend'],
        },
        {
            title: 'Email',
            dataIndex: 'email',
            key: 'email',
            sorter: (a, b) => a.email.localeCompare(b.email),
            sortDirections: ['ascend', 'descend'],
        },
        {
            title: 'Classe',
            dataIndex: 'classe',
            key: 'classe',
            render: (classe) => classe ? `${classe.nom} (${classe.niveau})` : 'N/A',
            sorter: (a, b) => {
                const aClasse = a.classe ? a.classe.nom : 'N/A';
                const bClasse = b.classe ? b.classe.nom : 'N/A';
                return aClasse.localeCompare(bClasse);
            },
            sortDirections: ['ascend', 'descend'],
        },
        {
            title: 'Actions',
            key: 'actions',
            render: (_, record) => (
                <Space size="middle">
                    <EditOutlined
                        className="text-red-500 cursor-pointer text-lg hover:text-red-700 transition-colors duration-200"
                        onClick={() => {
                            setSelectedStudent(record);
                            form.setFieldsValue({ ...record, classeId: record.classe?.id });
                            setModalVisible(true);
                        }}
                    />
                    <Popconfirm
                        title="Êtes-vous sûr de supprimer cet étudiant?"
                        onConfirm={() => handleDeleteEtudiant(record.id)}
                        okText="Oui"
                        cancelText="Non"
                    >
                        <DeleteOutlined className="text-red-500 cursor-pointer text-lg hover:text-red-700 transition-colors duration-200" />
                    </Popconfirm>
                </Space>
            ),
        },
    ];

    if (currentUser?.role !== 'ADMIN') {
        return (
            <Alert
                message="Accès non autorisé"
                description="Vous n'avez pas les permissions nécessaires pour voir cette section."
                type="error"
                showIcon
                className="rounded-lg shadow-md"
            />
        );
    }

    return (
        <div className="p-4">
            <Title level={2} className="text-center text-red-600 mb-8 font-extrabold">
                <TeamOutlined className="mr-2" />
                Gestion des Étudiants
            </Title>

            {/* Stats Cards Section */}
            <Row gutter={[16, 16]} className="mb-6">
                <Col xs={24} md={8}>
                    <Card bordered={false} className="bg-white p-4 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300">
                        <Statistic
                            title="Total des Étudiants"
                            value={etudiants.length}
                            valueStyle={{ color: '#cf1322' }}
                            prefix={<UserOutlined />}
                        />
                    </Card>
                </Col>
                <Col xs={24} md={8}>
                    <Card bordered={false} className="bg-white p-4 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300">
                        <Statistic
                            title="Total des Classes"
                            value={classes.length}
                            valueStyle={{ color: '#3f8600' }}
                            prefix={<TeamOutlined />}
                        />
                    </Card>
                </Col>
                <Col xs={24} md={8}>
                    <Card bordered={false} className="bg-white p-4 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300">
                        <Statistic
                            title="Étudiants sans classe"
                            value={etudiants.filter(s => !s.classe).length}
                            valueStyle={{ color: '#d46b08' }}
                            prefix={<UserOutlined />}
                        />
                    </Card>
                </Col>
            </Row>

            {/* Pie Chart Section */}
            {etudiants.length > 0 ? (
                <Row gutter={16} className="mb-6 justify-center">
                    <Col xs={24} md={12}>
                        <div className="bg-white p-4 rounded-lg shadow-md">
                            <Title level={4} className="text-center text-red-500">Répartition des Étudiants par Classe</Title>
                            <Pie data={pieData} options={pieOptions} />
                        </div>
                    </Col>
                </Row>
            ) : (
                <Alert
                    message="Aucune donnée pour le graphique"
                    description="Ajoutez des étudiants pour voir la répartition par classe."
                    type="info"
                    showIcon
                    className="mb-6 rounded-lg shadow-md"
                />
            )}

            <Space className="mb-6 w-full flex-wrap justify-between">
                <Space>
                    <Button
                        type="primary"
                        icon={<PlusCircleOutlined />}
                        onClick={() => {
                            setSelectedStudent(null);
                            form.resetFields();
                            setModalVisible(true);
                        }}
                        className="bg-red-500 hover:bg-red-600 rounded-lg px-6 py-3 text-lg font-semibold transition-all duration-300 shadow-md hover:shadow-lg"
                    >
                        Ajouter Étudiant
                    </Button>
                    <Button
                        type="default"
                        icon={<FilePdfOutlined />}
                        onClick={handleExportStudentsPdf}
                        loading={loading || !pdfLibsLoaded}
                        className="bg-red-500 hover:bg-red-600 border-none text-white rounded-lg px-6 py-3 text-lg font-semibold transition-all duration-300 shadow-md hover:shadow-lg"
                    >
                        Télécharger Étudiants (PDF)
                    </Button>
                </Space>
                <Input
                    placeholder="Rechercher par nom ou email"
                    prefix={<SearchOutlined />}
                    value={searchText}
                    onChange={e => setSearchText(e.target.value)}
                    style={{ width: 300 }}
                    className="rounded-lg border-gray-300 focus:border-red-500 transition-all duration-200"
                />
            </Space>

            <Table
                columns={columns}
                dataSource={filteredEtudiants}
                loading={loading}
                rowKey="id"
                className="ant-table-striped rounded-lg shadow-md"
                pagination={{ pageSize: 10 }}
            />

            <Modal
                title={<span className="text-red-500 text-2xl font-bold">{selectedStudent ? 'Modifier Étudiant' : 'Créer Nouvel Étudiant'}</span>}
                open={modalVisible}
                onCancel={() => {
                    setModalVisible(false);
                    form.resetFields();
                }}
                footer={null}
                destroyOnClose
                centered
                className="rounded-xl overflow-hidden shadow-2xl"
                bodyStyle={{ padding: '30px' }}
            >
                <Form
                    form={form}
                    layout="vertical"
                    onFinish={handleEtudiantSubmit}
                >
                    <Form.Item
                        name="nom"
                        label={<span className="text-gray-700 font-medium">Nom</span>}
                        rules={[{ required: true, message: 'Veuillez entrer le nom!' }]}
                    >
                        <Input
                            prefix={<UserOutlined className="text-red-500" />}
                            size="large"
                            className="rounded-lg border-gray-300 focus:border-red-500 focus:ring-red-500 transition-all duration-200"
                            placeholder="John Doe"
                        />
                    </Form.Item>
                    <Form.Item
                        name="email"
                        label={<span className="text-gray-700 font-medium">Email</span>}
                        rules={[{ required: true, type: 'email', message: 'Veuillez entrer un email valide!' }]}
                    >
                        <Input
                            prefix={<MailOutlined className="text-red-500" />}
                            size="large"
                            className="rounded-lg border-gray-300 focus:border-red-500 focus:ring-red-500 transition-all duration-200"
                            placeholder="exemple@esprit.tn"
                        />
                    </Form.Item>
                    <Form.Item
                        name="classeId"
                        label={<span className="text-gray-700 font-medium">Classe</span>}
                        rules={[{ required: true, message: 'Veuillez sélectionner une classe!' }]}
                    >
                        <Select
                            prefix={<TeamOutlined className="text-red-500" />}
                            size="large"
                            className="rounded-lg border-gray-300 focus:border-red-500 focus:ring-red-500 transition-all duration-200"
                            placeholder="Sélectionner une classe"
                            allowClear
                        >
                            {classes.map(cls => (
                                <Option key={cls.id} value={cls.id.toString()}>{cls.nom} ({cls.niveau})</Option>
                            ))}
                        </Select>
                    </Form.Item>
                    <Form.Item className="mt-6">
                        <Button
                            type="primary"
                            htmlType="submit"
                            block
                            size="large"
                            className="bg-red-500 hover:bg-red-600 border-none rounded-lg px-6 py-3 text-lg font-semibold transition-all duration-300 shadow-md hover:shadow-lg"
                        >
                            {selectedStudent ? 'Mettre à jour' : 'Créer'} Étudiant
                        </Button>
                    </Form.Item>
                </Form>
            </Modal>
        </div>
    );
};

export default StudentManagement;